.global P3DS_ProfRet
.type P3DS_ProfRet,%function
P3DS_ProfRet:
 push {r0-r5,r12,lr}
 vpush {d0-d7}
 bl P3DS_ProfExit
 str r0,[sp,#92]
 vpop {d0-d7}
 pop {r0-r5,r12,lr}
 bx lr
.global __wrap_ARNG_Next
.type __wrap_ARNG_Next,%function
__wrap_ARNG_Next:
